mapper.select:
/** [PCM] selectProjectCodeList - 평가코드 조회(본부장) */ SELECT B.VESTICODE as "vEstiCode" /* 01_평가코드 */ , B.VPROJECTCODE as "vProjectCode" /* 02_과제코드 */ , B.VPROJECTNAME as "vProjectName" /* 03_과제명 */ , B.VDEPTNAME as "vDeptName" /* 04_센터명 */ , B.VGOVNAME as "vGovName" /* 05_부처명 */ , B.VPROJECTDIVISION as "vProjectDivision" /* 06_사업명 */ , B.VTOTSTARTDATE as "vTotStartDate" /* 07_총과제시작일 */ , B.VTOTENDDATE as "vTotEndDate" /* 08_총과제종료일 */ , B.VSTARTDATE as "vStartDate" /* 09_과제시작일 */ , B.VENDDATE as "vEndDate" /* 10_과제종료일 */ , B.VPROJECTPM as "vProjectPm" /* 11_과제 PM */ , ( SELECT A.VNAME FROM TCA4002 A WHERE A.VESTICODE = B.VESTICODE AND A.VEMPLNO = B.VPROJECTPM ) as "vProjectPmName" /* 12_과제 PM명 */ , B.VPROJECTEVA as "vProjectEva" /* 13_과제 평가자 */ , ( SELECT A.VNAME FROM TCA4002 A WHERE A.VESTICODE = B.VESTICODE AND A.VEMPLNO = B.VPROJECTEVA ) as "vProjectEvaName" /* 14_과제 평가자명 */ , B.VPROJECTGOAL as "vProjectGoal" /* 15_과제 목표 */ , B.VPROJECTMILESTONE as "vProjectMilestone" /* 16_평가 기간내 Milestone */ , B.VESTISTEP as "vEstiStep" /* 17_과제 진행단계 */ , ( SELECT DECODE(INSTR(SUBSTR(XMLAGG(XMLELEMENT(A, NVL(A.VCONFIRM, 'N'))).EXTRACT('//text()'),1), 'N'), 0, 'Y', 'N') FROM TCA4005 A WHERE A.VESTICODE = B.VESTICODE AND A.VPROJECTCODE = B.VPROJECTCODE ) as "vConfirm" /* 18_확인여부 */ , ( SELECT DECODE(INSTR(SUBSTR(XMLAGG(XMLELEMENT(A, NVL(A.VFINISH, 'N'))).EXTRACT('//text()'),1), 'N'), 0, 'Y', 'N') FROM TCA4005 A WHERE A.VESTICODE = B.VESTICODE AND A.VPROJECTCODE = B.VPROJECTCODE ) as "vFinish" /* 19_완료여부 */ FROM TCA4003 B
B.VESTICODE = #{vEstiCode, jdbcType=VARCHAR}
AND B.VDEPTNAME IN
#{deptName}
ORDER BY B.VPROJECTCODE

/** pjaSql - selectProjectEmpList - 참여연구원 기여율 목록 조회 */ SELECT A.VESTICODE as "vEstiCode" , A.VPROJECTCODE as "vProjectCode" , A.VEMPLNO as "vEmplNo" , B.VNAME as "vName" , C.VTEAMNAME as "vDeptName" , D.VTEAMNAME as "vTeamName" , E.VPOSNAME as "vPosName" , A.NCONTRIBUTION as "nContribution" , A.VCONTENT as "vContent" , A.VCONFIRM as "vConfirm" , A.VFINISH as "vFinish" FROM TCA4005 A, TCA4002 F, TAA2101 B, (SELECT VTEAMCODE, VTEAMNAME FROM TAZ2001 WHERE VTEAMFLAG IN ('1', '2')) C, (SELECT VTEAMCODE, VTEAMNAME FROM TAZ2001 WHERE VTEAMFLAG = '3' ORDER BY VHIGHTEAM, VTEAMCODE) D, (SELECT VPOSCODE, VPOSNAME, VGRADENAME FROM TAZ2003) E
A.VESTICODE = #{vEstiCode} AND A.VPROJECTCODE = #{vProjectCode} AND A.VESTICODE = F.VESTICODE AND A.VEMPLNO = F.VEMPLNO AND F.VESTIYN = 'Y' AND A.VEMPLNO = B.VEMPLNO AND B.VDEPTCODE = C.VTEAMCODE(+) AND B.VTEAMCODE = D.VTEAMCODE(+) AND B.VPOSCODE = E.VPOSCODE(+)
ORDER BY B.VDEPTCODE, B.VTEAMCODE, B.VPOSCODE, B.NESTIPOINT DESC

/** pjaSql - selectReview - 평가의견 조회 */
SELECT
   VREVIEWCONTENT   as "vReviewContent"
FROM
   TCA4006

       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND NSEQNO = (
                 SELECT
                    MAX(NSEQNO)
                 FROM
                    TCA4006
                 WHERE
                        VESTICODE = #{vEstiCode}
                    AND VPROJECTCODE = #{vProjectCode}
              )

mapper.insert:
      /** pjaSql - insertReview - 평가의견 저장 */
      
         SELECT
            NVL(MAX(NSEQNO), 0) + 1   as "nSeqNo"
         FROM
            TCA4006
         
                VESTICODE = #{vEstiCode}
            AND VPROJECTCODE = #{vProjectCode}
         
      

      INSERT INTO
         TCA4006
         (
              VESTICODE
            , VPROJECTCODE
            , NSEQNO
            , VREVIEWCONTENT
         )
      VALUES
         (
              #{vEstiCode}
            , #{vProjectCode}
            , #{nSeqNo}
            , #{vReviewContent}
         )

mapper.update:
/** pjaSql - updateEstiStep3 - 평가자가 반려 */
UPDATE TCA4003
   SET
      VESTISTEP = '3'

       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND VPROJECTEVA = #{vProjectEva}

/** pjaSql - updateEstiStep4 - 평가자가 완료(승인) */
UPDATE TCA4003
   SET
      VESTISTEP = '4'

       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND VPROJECTEVA = #{vProjectEva}
